insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-04','verbeterd','Klantportaal','De planning laat nu ook de activiteiten zien',
   'In het klantportaal stonden alleen de fases met hun begin- en einddatum. Onder elke fase staan nu de losse activiteiten, in dezelfde volgorde als in de detailplanning. Het aparte vinkje hiervoor op de Portaal-tab is vervallen; namen van medewerkers blijven zoals altijd buiten beeld.');
